      const comb = (ku, kv) => { const a = new Array(D + 1).fill(0); for (let i = 0; i <= pu; i++) for (let j = 0; j <= pv; j++) { const f = bu[ku][i] * bv[kv][j], h = G[su - pu + i][sv - pv + j]; for (let c = 0; c <= D; c++) a[c] += f * h[c]; } return a; };
