    closureType: ['SFString', INIT, "PIE"],
    endAngle: ['SFFloat', INIT, 1.570796],
    metadata: ['SFNode', IO, null],
    radius: ['SFFloat', INIT, 1],
    solid: ['SFBool', INIT, false],
    startAngle: ['SFFloat', INIT, 0],
