    child2Url: ['MFString', INIT, []],
    child3Url: ['MFString', INIT, []],
    child4Url: ['MFString', INIT, []],
    children: ['MFNode', OUT, []],
    geoOrigin: ['SFNode', INIT, null],
    geoSystem: ['MFString', INIT, ['GD', 'WE']],
