  component: 'CubeMapTexturing', level: 2,
  container: 'texture',
  defs: {
    autoRefresh: ['SFTime', IO, 0],
    autoRefreshTimeLimit: ['SFTime', IO, 3600],
    description: ['SFString', IO, ""],
    load: ['SFBool', IO, true],
    metadata: ['SFNode', IO, null],
    textureProperties: ['SFNode', INIT, null],
    url: ['MFString', IO, []],
  },
