    p.distanceModel = BR.snd.types.SpatialSound.dist[f.distanceModel] || 'inverse';
    p.rolloffFactor = p.distanceModel === 'linear' ? Math.min(Math.max(f.rolloffFactor, 0), 1) : Math.max(f.rolloffFactor, 0);
