V.fl = fl;
V.v3 = (a) => `vec3f(${fl(a[0])}, ${fl(a[1])}, ${fl(a[2])})`;
V.v4 = (a) => `vec4f(${fl(a[0])}, ${fl(a[1])}, ${fl(a[2])}, ${fl(a.length > 3 ? a[3] : 1)})`;
