        let gn = vec3f(vox(tc - vec3f(o.x, 0.0, 0.0)).r - vox(tc + vec3f(o.x, 0.0, 0.0)).r, vox(tc - vec3f(0.0, o.y, 0.0)).r - vox(tc + vec3f(0.0, o.y, 0.0)).r, vox(tc - vec3f(0.0, 0.0, o.z)).r - vox(tc + vec3f(0.0, 0.0, o.z)).r);
